/**  Id de um Cofre (ENT-02). */
export type CofreId = string;

/**
 *  Resultado salvo com avisos (tratamento `avisar`: o valor foi salvo e o Humano decide,
 *  ex.: ERR-47 limite fora da faixa recomendada).
 */
export type ComAvisos<T> = {
  valor: T;
  avisos: ErroCatalogo[];
};

/**  ENT-14 Consumo (a última leitura). `excedente` fica fora da tela por ora. */
export type Consumo = {
  /**  Percentual inteiro, 0 a 100. */
  semanal_pct: number;
  /**  Percentual inteiro, 0 a 100. */
  janela_pct: number;
  /**  Reinício da janela de 5 h. */
  proximo_reinicio: DataHoraUtc;
  /**  Reinício da semana de 7 dias. */
  semanal_reinicio: DataHoraUtc;
  lida_em: DataHoraUtc;
  origem: OrigemConsumo;
  janela_status: StatusConsumo;
  semanal_status: StatusConsumo;
};

/**  Leitura nova de consumo (CMP-01), ou o aviso de status desconhecido (ERR-50). */
export type ConsumoAtualizado = {
  consumo: Consumo;
  avisos: ErroCatalogo[];
};

/**  ENT-24 Critério. */
export type Criterio = {
  status: StatusCriterio;
  /**  Saída de teste, captura ou resposta; obrigatória para `passou` (ERR-20). */
  prova: string | null;
};

/**
 *  Data e hora em ISO 8601 UTC com `Z` (ex.: `2026-11-19T18:20:00Z`), com fração de
 *  segundo opcional (até 9 casas). Qualquer outro formato é recusado na entrada e na
 *  saída, então a tela nunca recebe hora local nem deslocamento (`-03:00`).
 */
export type DataHoraUtc = string;

/**  `decisao` de ENT-10. */
export type DecisaoAchado = "corrigir" | "limite" | "opcional";

/**  Um item do catálogo com os valores do momento (`<x>` da mensagem). */
export type ErroCatalogo = {
  /**  Código no servidor; a tela escolhe a mensagem por ele. */
  codigo: CodigoErro;
  /**  Id no catálogo (`ERR-xx`), para log e teste. */
  id: string;
  /**  Valores preenchidos em tempo de execução (ex.: `integracao`, `motivo`), mascarados. */
  parametros: { [key in string]: string };
};

/**
 *  Erro de um comando. `catalogo` é a regra (o código diz o quê); falha inesperada do
 *  núcleo é o ERR-55 `FALHA_INTERNA` ([`ErroIpc::falha_interna`]). `interno` só resta no
 *  corpo provisório dos comandos ainda sem núcleo, até a T4 do integracoes-plano.
 */
export type ErroIpc =
  { tipo: "catalogo"; erro: ErroCatalogo } | { tipo: "interno"; motivo: MotivoInterno };

/**
 *  Saída ao vivo de uma execução, pelo canal aberto em `enviar_prompt` ou
 *  `acompanhar_execucao` (CMP-04). Os textos já chegam mascarados (RN-04).
 */
export type EventoExecucao =
  /**  Pedaço de texto da resposta, na ordem em que chega. */
  | { tipo: "texto"; texto: string }
  /**  Uso de uma ferramenta pelo agente (só o nome e um resumo curto). */
  | { tipo: "ferramenta"; nome: string; resumo: string }
  /**  Mensagem completa gravada no chat. */
  | { tipo: "mensagem"; mensagem: Mensagem }
  /**  Total de tokens usados pela execução até aqui. */
  | { tipo: "uso_tokens"; tokens_usados: number }
  /**  O orquestrador propôs um plano (abre o CMP-10). */
  | { tipo: "plano_proposto"; plano: PlanoId }
  /**  A execução mudou de status; `concluido`, `falhou` e `interrompida` fecham o canal. */
  | { tipo: "status"; status: StatusExecucao }
  /**  Erro do catálogo durante a execução (ex.: ERR-17, ERR-08). */
  | { tipo: "erro"; erro: ErroCatalogo };

/**  ENT-07 Execução (o que a tela de execução mostra, inclusive os comandos). */
export type Execucao = {
  id: ExecucaoId;
  chat: ChatId;
  /**  Vazio só para o orquestrador. */
  tarefa: TarefaId | null;
  papel: NomePapel;
  modelo: string;
  prompt_versao: number;
  /**  Obrigatórios para `funcionalidade` (ERR-16). */
  worktree: string | null;
  branch: string | null;
  status: StatusExecucao;
  /**  Só quando `status = na_fila`. */
  motivo_fila: MotivoFila | null;
  /**
   *  Comandos executados pelo agente, mascarados (RN-04); push, merge e push --force
   *  nunca entram, porque o núcleo os nega antes (RN-17, ERR-14).
   */
  comandos: string[];
};

/**  Id de uma Execução (ENT-07). */
export type ExecucaoId = string;

/**  Uma execução foi criada ou mudou de status (CMP-04, CMP-05). */
export type ExecucaoMudou = {
  execucao: Execucao;
};

/**  `fluxo` de ENT-08. */
export type FluxoPrompt =
  "orquestrador" | "funcionalidade" | "teste" | "adversarial" | "passagem_de_turno";

/**  `funcao` de ENT-02. */
export type FuncaoCofre = "memoria" | "consulta";

/**  Instrução para o Humano durante a conexão (UC-01 passo 2), pelo canal do comando. */
export type InstrucaoConexao =
  /**  Device flow do GitHub: digitar `codigo` em `endereco`. */
  | { tipo: "codigo_do_dispositivo"; codigo: string; endereco: string }
